/// Arsenal's patch: the window's player's own name, from the player list.
pub(super) fn arsenal_own_name(&self) -> Option<String> {
    let r = self.remote.as_ref()?;
    r.players.get(&r.profile).cloned()
}

/// Sends a chat message or (with `/`) a command, as typing it in the chat box does (Arsenal's patch).
pub(super) fn native_send_chat(&mut self, text: &str) {
    self.handle_chat_input(text);
}
/// The chat lines shown since the last call, oldest first, as plain text (Arsenal's patch).
pub(super) fn native_take_chat(&mut self) -> Vec<String> {
    std::mem::take(&mut self.ui.chat.arsenal_inbox)
}
/// The window's player's own name (Arsenal's patch): none before joining a world.
pub(super) fn native_own_name(&self) -> Option<String> {
    self.arsenal_own_name()
}
